effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  vec3 warm = vec3(1.07, 0.94, 0.74);
  vec3 cool = vec3(0.90, 0.93, 1.00);
  vec3 sep = vec3(l) * mix(cool, warm, warmth);
  sep.r *= 1.0 + 0.10 * warmth;
  sep.b *= 1.0 - 0.10 * warmth;
  vec3 col = mix(c, clamp(sep, 0.0, 1.0), amount * mixAmt);
  gl_FragColor = vec4(col * a, a);
}
